import { useState } from 'react'
import { Button } from '../../components/Button'
import { Card } from '../../components/Card'
import { activeTrip } from '../../services/tripService'
import { apiRequest } from '../../services/apiClient'

export function BusinessTripsPage(){const tripId=activeTrip.get();const [company,setCompany]=useState('');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const save=async()=>{if(!tripId||!company.trim())return;setBusy(true);setMessage('');try{await apiRequest(`/trips/${tripId}`,{method:'PATCH',body:JSON.stringify({companyName:company.trim(),tripType:'business'})});setMessage('Business trip profile saved. The same itinerary can now be edited for your employee group.')}catch(e){setMessage(e instanceof Error?e.message:'Unable to save business trip.')}finally{setBusy(false)}};return <section className="page-stack"><div><p className="eyebrow">More · Business trips</p><h1 className="page-title">Plan business travel for your team.</h1><p className="page-copy">Attach the current trip to an organization and use group collaboration for employee travelers.</p></div><Card><h2>Organization profile</h2><input className="tp-input" value={company} onChange={e=>setCompany(e.target.value)} placeholder="Company / organization name"/><Button disabled={busy||!tripId} onClick={()=>void save()}>{busy?'Saving…':'Save business trip'}</Button>{message&&<p className="auth-inline-message">{message}</p>}</Card><Card><h2>Workflow</h2><p className="page-copy">Create the plan → add employee travelers under Group Trip → customize the itinerary → submit the finalized plan for admin approval → pay only after approval.</p></Card></section>}
